var gm=UnityEngine.Object.FindObjectOfType<GameManager>();var wm=UnityEngine.Object.FindObjectOfType<WaveManager>();var castle=UnityEngine.Object.FindObjectOfType<Base>();
var towers=new System.Collections.Generic.List<object>();foreach(var tower in UnityEngine.Object.FindObjectsOfType<Tower>()){
 var damage=typeof(Tower).GetField("currentDamage",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(tower);
 towers.Add(new{id=tower.GetInstanceID(),type=tower.data.type.ToString(),level=tower.Level,xp=tower.Experience,element=tower.SelectedElement.ToString(),position=tower.transform.position.ToString(),items=tower.Backpack!=null?tower.Backpack.Items.Count:0,damage=damage,range=tower.CurrentRange});}
var enemies=UnityEngine.Object.FindObjectsOfType<Enemy>();float health=0;foreach(var e in enemies)health+=e.CurrentHealth;
return Newtonsoft.Json.JsonConvert.SerializeObject(new{scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().name,loading=SceneLoadingUI.IsLoading,frame=UnityEngine.Time.frameCount,time=UnityEngine.Time.time,state=gm!=null?gm.CurrentState.ToString():"Menu",paused=gm!=null&&gm.IsPaused,chapter=wm!=null&&wm.ActiveChapter!=null?wm.ActiveChapter.chapterNumber:0,wave=wm!=null?wm.CurrentWaveIndex:0,waves=wm!=null?wm.waves.Count:0,gold=EconomyManager.Gold,hp=castle!=null?castle.currentHealth:0,maxHp=castle!=null?castle.maxHealth:0,enemies=enemies.Length,enemyHp=health,towers=towers});
